#!/usr/bin/env bash
# hotpatch_sidebar.sh — Admin sidebar: grouped + compact
set -e
APP="/home/axisai/axis-frontend"
GREEN='\033[0;32m'; CYAN='\033[0;36m'; RESET='\033[0m'
log() { echo -e "${CYAN}[patch]${RESET} $*"; }
ok()  { echo -e "${GREEN}[  OK  ]${RESET} $*"; }

echo ""; echo "  Admin Sidebar Compact Redesign"; echo ""

log "Patching components/layout/sidebar.tsx..."
echo "" | base64 -d > "$APP/components/layout/sidebar.tsx"
ok "Sidebar patched"

log "Building Next.js..."
cd "$APP"
npm run build 2>&1 | tail -20

log "Reloading pm2..."
pm2 reload axis-frontend --update-env
ok "Done!"
echo ""
echo -e "${GREEN}  ✓ Sidebar hotpatch complete!${RESET}"
